package org.apache.commons.math.analysis;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BrentSolver_solve_TriageGen1Test {

    /**
     * Mock function to control return values for different test scenarios.
     */
    private static class MockFunction implements UnivariateRealFunction {
        private final double minVal;
        private final double maxVal;

        public MockFunction(double minVal, double maxVal) {
            this.minVal = minVal;
            this.maxVal = maxVal;
        }

        @Override
        public double value(double x) {
            // In a real scenario, we'd map x to values, 
            // but for branch coverage of the solve method, 
            // we simulate the yMin and yMax logic.
            if (x == 0.0) return minVal; // Using 0.0 as a sentinel for 'min'
            if (x == 1.0) return maxVal; // Using 1.0 as a sentinel for 'max'
            return 0.0;
        }
    }

    @Test
    public void testSolve_SignNegative_Success() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign < 0 (yMin * yMax < 0)
        // This triggers the branch: ret = solve(min, yMin, max, yMax, min, yMin);
        UnivariateRealFunction f = x -> (x < 0.5) ? -1.0 : 1.0;
        BrentSolver solver = new BrentSolver(f);

        // We use a simple function where the root is known.
        // Note: The actual BrentSolver implementation will call f.value multiple times.
        double result = solver.solve(-1.0, 1.0);
        assertEquals(0.5, result, 1e-7);
    }

    @Test
    public void testSolve_SignZero_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign == 0 and yMin == 0.0
        UnivariateRealFunction f = x -> (x == -1.0) ? 0.0 : 1.0;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(-1.0, 1.0);
        assertEquals(-1.0, result, 0.0);
    }

    @Test
    public void testSolve_SignZero_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign == 0 and yMin != 0.0 (so yMax must be 0.0)
        UnivariateRealFunction f = x -> (x == -1.0) ? 1.0 : 0.0;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(-1.0, 1.0);
        assertEquals(1.0, result, 0.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_SignPositive_ThrowsException() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign > 0 and yMin is not close to zero and yMax is not close to zero
        // This triggers the IllegalArgumentException branch.
        UnivariateRealFunction f = x -> 1.0; 
        BrentSolver solver = new BrentSolver(f);

        solver.solve(-1.0, 1.0);
    }

    @Test
    public void testSolve_SignPositive_MinCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign > 0 and Math.abs(yMin) <= functionValueAccuracy
        // Note: functionValueAccuracy is typically a small epsilon.
        // We need to find a way to trigger this. Since we can't easily set private fields, 
        // we rely on the default small epsilon.
        double epsilon = 1e-10; 
        UnivariateRealFunction f = x -> (x == -1.0) ? epsilon : 1.0;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(-1.0, 1.0);
        assertEquals(-1.0, result, 0.0);
    }

    @Test
    public void testSolve_SignPositive_MaxCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign > 0 and Math.abs(yMax) == functionValueAccuracy
        // This is a very specific branch condition in the provided code.
        // We assume the solver's internal accuracy matches our epsilon.
        double epsilon = 1e-10; 
        UnivariateRealFunction f = x -> (x == -1.0) ? 1.0 : epsilon;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(-1.0, 1.0);
        assertEquals(1.0, result, 0.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidInterval() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Implicitly tests verifyInterval(min, max) via the solve method
        UnivariateRealFunction f = x -> x;
        BrentSolver solver = new BrentSolver(f);

        // min > max should trigger verifyInterval error
        solver.solve(1.0, -1.0);
    }
}
